import numpy as np

INDEX = {c: i for i, c in enumerate(".abcdefghijklmnopqrstuvwxyz")}


def build_dataset(words, block):
    X, Y = [], []
    for w in words:
        context = [0] * block
        for ch in w + ".":
            ix = INDEX[ch]
            X.append(context)
            Y.append(ix)
            context = context[1:] + [ix]
    return np.array(X), np.array(Y)

